def S(N):
    """Calculates S(N) = sum_{a=1}^{N} sum_{b=1}^{N} floor(ab/(N+1))"""
    total_sum = 0
    D = N + 1
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            total_sum += (a * b) // D
    return total_sum

def T(N):
    """Calculates T(N) = (N^3 - N^2 + 2) / 4"""
    return (N**3 - N**2 + 2) / 4

Ns = [1, 2, 3, 4]
results = {}
for N in Ns:
    s_val = S(N)
    t_val = T(N)
    results[N] = {'S(N)': s_val, 'T(N)': t_val, 'Match': s_val == t_val}

print(results)

def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

